// Package main tests for the Dagger CI module.
//
// These tests exercise the generated shell fragments (readinessScript and
// acceptanceScript) by running them under /bin/sh with stub curl, date, sleep,
// go and gotestsum executables. The stubs let the tests cover connection
// refusal, TLS/empty-reply failures, transient HTTP statuses, red/timed-out
// health, fail-fast authentication, malformed bodies, template rejection and
// the bounded diagnostics without a live Elasticsearch.
//
// Harness requirements: the Dagger Go module SDK (dagger.gen.go and
// internal/dagger) is generated by `dagger develop` and is intentionally not
// committed, so a fresh `go test ./ci/dagger` cannot compile. The generated
// SDK's init also requires DAGGER_SESSION_PORT and DAGGER_SESSION_TOKEN; the
// module environment provides them. For local runs of these pure shell tests
// the generated SDK is present after `dagger develop` and any non-empty values
// work, e.g. `DAGGER_SESSION_PORT=1 DAGGER_SESSION_TOKEN=test go test ./...`.
//
// Not unit-testable here: real service-startup failures (for example an invalid
// Elasticsearch setting) and the boundary between Dagger's exposed-port TCP
// health check and the readiness loop. Those are validated with disposable
// Dagger failure injections against the real fixture.
package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// scenarioStep describes one simulated curl response. rc is the curl exit code,
// status the value printed by --write-out and kind the pre-canned body.
type scenarioStep struct {
	rc     string
	status string
	body   string
}

const stubClockStart = 1000000

// stubEnv prepares a temporary PATH containing stub date, sleep, curl, go and
// gotestsum executables plus the scenario/clock files the stubs coordinate
// through. It returns the stub dir (exposed via ES_STUB_DIR) and the bin dir.
func stubEnv(t *testing.T, steps []scenarioStep) (string, string) {
	t.Helper()
	dir := t.TempDir()
	bin := filepath.Join(dir, "bin")
	if err := os.MkdirAll(bin, 0o755); err != nil {
		t.Fatalf("mkdir bin: %v", err)
	}

	var scenario strings.Builder
	for _, s := range steps {
		scenario.WriteString(s.rc + "|" + s.status + "|" + s.body + "\n")
	}
	writeFile(t, filepath.Join(dir, "scenario"), scenario.String(), 0o644)
	writeFile(t, filepath.Join(dir, "clock"), strconv.Itoa(stubClockStart), 0o644)

	writeFile(t, filepath.Join(bin, "date"), `#!/bin/sh
cat "$ES_STUB_DIR/clock"
`, 0o755)
	writeFile(t, filepath.Join(bin, "sleep"), `#!/bin/sh
c=$(cat "$ES_STUB_DIR/clock")
echo $(( c + $1 )) > "$ES_STUB_DIR/clock"
`, 0o755)
	writeFile(t, filepath.Join(bin, "curl"), `#!/bin/sh
d="$ES_STUB_DIR"
n=0
[ -f "$d/count" ] && n=$(cat "$d/count")
n=$(( n + 1 ))
echo "$n" > "$d/count"
line=$(sed -n "${n}p" "$d/scenario")
[ -z "$line" ] && line=$(tail -n 1 "$d/scenario")
rc=${line%%|*}
rest=${line#*|}
status=${rest%%|*}
kind=${rest#*|}
out=/dev/null
prev=
for a in "$@"; do
  if [ "$prev" = "--output" ]; then out="$a"; fi
  prev="$a"
done
case "$kind" in
  green) printf '{"status":"green","timed_out":false,"number_of_nodes":1}' > "$out" ;;
  yellow) printf '{"status":"yellow","timed_out":false}' > "$out" ;;
  red) printf '{"status":"red","timed_out":false}' > "$out" ;;
  timedout) printf '{"status":"red","timed_out":true}' > "$out" ;;
  malformed) printf 'not-json' > "$out" ;;
  acktrue) printf '{"acknowledged":true}' > "$out" ;;
  ackfalse) printf '{"acknowledged":false}' > "$out" ;;
  err) printf '{"error":"simulated"}' > "$out" ;;
  empty) : > "$out" ;;
  *) : > "$out" ;;
esac
if [ "$rc" != "0" ]; then
  printf 'curl: (%s) simulated failure\n' "$rc" >&2
fi
printf '%s' "$status"
exit "$rc"
`, 0o755)
	writeFile(t, filepath.Join(bin, "go"), `#!/bin/sh
touch "$ES_STUB_DIR/go_called"
`, 0o755)
	writeFile(t, filepath.Join(bin, "gotestsum"), `#!/bin/sh
touch "$ES_STUB_DIR/gotestsum_called"
`, 0o755)
	return dir, bin
}

func writeFile(t *testing.T, path, content string, mode os.FileMode) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), mode); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
}

// runScript executes the shell fragment with the stubs first on PATH and the
// consumer environment variables set. It returns combined output and exit code.
func runScript(t *testing.T, script string, steps []scenarioStep) (string, int, string) {
	t.Helper()
	dir, bin := stubEnv(t, steps)
	cmd := exec.Command("sh", "-c", script)
	cmd.Env = append(os.Environ(),
		"PATH="+bin+":"+os.Getenv("PATH"),
		"ES_STUB_DIR="+dir,
		"ELASTICSEARCH_URL="+elasticsearchURL,
		"ELASTICSEARCH_USERNAME="+username,
		"ELASTICSEARCH_PASSWORD=stub-secret",
	)
	out, err := cmd.CombinedOutput()
	code := 0
	if err != nil {
		exitErr, ok := err.(*exec.ExitError)
		if !ok {
			t.Fatalf("run script: %v (output %q)", err, out)
		}
		code = exitErr.ExitCode()
	}
	return string(out), code, dir
}

func clockValue(t *testing.T, dir string) int {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(dir, "clock"))
	if err != nil {
		t.Fatalf("read clock: %v", err)
	}
	v, err := strconv.Atoi(strings.TrimSpace(string(raw)))
	if err != nil {
		t.Fatalf("parse clock %q: %v", raw, err)
	}
	return v
}

func markerExists(t *testing.T, dir, name string) bool {
	t.Helper()
	_, err := os.Stat(filepath.Join(dir, name))
	return err == nil
}

// TestReadinessRetriesTransientThenSucceeds covers connection refusal, TLS
// error and empty reply followed by 503/429, red/timed-out health and finally a
// healthy green response.
func TestReadinessRetriesTransientThenSucceeds(t *testing.T) {
	steps := []scenarioStep{
		{"7", "000", "empty"},
		{"35", "000", "empty"},
		{"52", "000", "empty"},
		{"0", "503", "err"},
		{"0", "429", "err"},
		{"0", "200", "red"},
		{"0", "200", "timedout"},
		{"0", "200", "green"},
	}
	out, code, _ := runScript(t, readinessScript(), steps)
	if code != 0 {
		t.Fatalf("expected success, got exit %d:\n%s", code, out)
	}
	if !strings.Contains(out, "ready") {
		t.Fatalf("expected readiness success message, got:\n%s", out)
	}
	if !strings.Contains(out, "attempt=8") {
		t.Fatalf("expected 8 attempts, got:\n%s", out)
	}
}

// TestReadinessAuthFailsFast verifies HTTP 401 stops immediately without
// burning the whole deadline.
func TestReadinessAuthFailsFast(t *testing.T) {
	out, code, dir := runScript(t, readinessScript(), []scenarioStep{{"0", "401", "err"}})
	if code == 0 {
		t.Fatalf("expected failure on 401:\n%s", out)
	}
	if !strings.Contains(out, "authentication rejected") {
		t.Fatalf("expected authentication error, got:\n%s", out)
	}
	if got := clockValue(t, dir); got != stubClockStart {
		t.Fatalf("401 must not retry: clock moved from %d to %d", stubClockStart, got)
	}
}

// TestReadinessMalformed200Fails verifies an unexpected 200 body is rejected
// with its body included.
func TestReadinessMalformed200Fails(t *testing.T) {
	out, code, _ := runScript(t, readinessScript(), []scenarioStep{{"0", "200", "malformed"}})
	if code == 0 {
		t.Fatalf("expected failure on malformed 200:\n%s", out)
	}
	if !strings.Contains(out, "malformed health response") {
		t.Fatalf("expected malformed diagnostic, got:\n%s", out)
	}
	if !strings.Contains(out, "not-json") {
		t.Fatalf("expected response body in diagnostics, got:\n%s", out)
	}
}

// TestReadinessPermanentFailureExhausts verifies a permanent refusal retries
// until the full 180s budget and exits nonzero with bounded diagnostics.
func TestReadinessPermanentFailureExhausts(t *testing.T) {
	out, code, dir := runScript(t, readinessScript(), []scenarioStep{{"7", "000", "empty"}})
	if code == 0 {
		t.Fatalf("expected exhaustion failure:\n%s", out)
	}
	if !strings.Contains(out, "Elasticsearch HTTPS readiness failed after 180s") {
		t.Fatalf("expected exhaustion message, got:\n%s", out)
	}
	if got, want := clockValue(t, dir), stubClockStart+180; got != want {
		t.Fatalf("expected clock %d after exhaustion, got %d", want, got)
	}
}

// TestReadinessNonTransientCurlFailsFast verifies curl invocation errors (rc=2)
// do not retry.
func TestReadinessNonTransientCurlFailsFast(t *testing.T) {
	out, code, dir := runScript(t, readinessScript(), []scenarioStep{{"2", "000", "empty"}})
	if code == 0 {
		t.Fatalf("expected failure on non-transient curl rc:\n%s", out)
	}
	if !strings.Contains(out, "non-transient curl error") {
		t.Fatalf("expected non-transient diagnostic, got:\n%s", out)
	}
	if got := clockValue(t, dir); got != stubClockStart {
		t.Fatalf("non-transient error must not retry: clock moved to %d", got)
	}
}

// TestReadinessRetriesRedirectAndUnexpected4xxFails verifies 3xx/4xx fail fast.
func TestReadinessUnexpectedHTTPFailsFast(t *testing.T) {
	out, code, _ := runScript(t, readinessScript(), []scenarioStep{{"0", "404", "err"}})
	if code == 0 {
		t.Fatalf("expected failure on 404:\n%s", out)
	}
	if !strings.Contains(out, "unexpected HTTP 404") {
		t.Fatalf("expected unexpected-HTTP diagnostic, got:\n%s", out)
	}
}

// TestAcceptanceTemplateFailureStopsBeforeTests verifies a rejected template
// aborts before gotestsum even starts.
func TestAcceptanceTemplateFailureStopsBeforeTests(t *testing.T) {
	steps := []scenarioStep{
		{"0", "200", "green"},
		{"0", "400", "err"},
	}
	out, code, dir := runScript(t, readinessScript()+acceptanceScript(""), steps)
	if code == 0 {
		t.Fatalf("expected template failure:\n%s", out)
	}
	if !strings.Contains(out, "index template PUT failed") {
		t.Fatalf("expected template diagnostic, got:\n%s", out)
	}
	if markerExists(t, dir, "go_called") || markerExists(t, dir, "gotestsum_called") {
		t.Fatalf("tests must not run after a rejected template")
	}
}

// TestAcceptanceUnacknowledgedTemplateStops verifies a 200 without
// acknowledged=true is treated as a failure.
func TestAcceptanceUnacknowledgedTemplateStops(t *testing.T) {
	steps := []scenarioStep{
		{"0", "200", "green"},
		{"0", "200", "ackfalse"},
	}
	out, code, dir := runScript(t, readinessScript()+acceptanceScript(""), steps)
	if code == 0 {
		t.Fatalf("expected unacknowledged template failure:\n%s", out)
	}
	if !strings.Contains(out, "index template PUT failed") {
		t.Fatalf("expected template diagnostic, got:\n%s", out)
	}
	if markerExists(t, dir, "gotestsum_called") {
		t.Fatalf("tests must not run after unacknowledged template")
	}
}

// TestAcceptanceTemplateSuccessRunsTests verifies the happy path reaches the
// test runner.
func TestAcceptanceTemplateSuccessRunsTests(t *testing.T) {
	steps := []scenarioStep{
		{"0", "200", "green"},
		{"0", "200", "acktrue"},
	}
	out, code, dir := runScript(t, readinessScript()+acceptanceScript(""), steps)
	if code != 0 {
		t.Fatalf("expected success, got exit %d:\n%s", code, out)
	}
	if !markerExists(t, dir, "go_called") || !markerExists(t, dir, "gotestsum_called") {
		t.Fatalf("expected gotestsum to run after a valid template")
	}
}

// TestReadinessBodyBounded verifies diagnostics never dump more than 8 KiB of a
// response body.
func TestReadinessBodyBounded(t *testing.T) {
	dir, bin := stubEnv(t, []scenarioStep{{"0", "200", "malformed"}})
	// Replace the stub curl so it writes a large malformed body.
	writeFile(t, filepath.Join(bin, "curl"), `#!/bin/sh
d="$ES_STUB_DIR"
out=/dev/null
prev=
for a in "$@"; do
  if [ "$prev" = "--output" ]; then out="$a"; fi
  prev="$a"
done
i=0
: > "$out"
while [ "$i" -lt 20000 ]; do
  printf 'x' >> "$out"
  i=$(( i + 1 ))
done
printf '200'
`, 0o755)

	cmd := exec.Command("sh", "-c", readinessScript())
	cmd.Env = append(os.Environ(),
		"PATH="+bin+":"+os.Getenv("PATH"),
		"ES_STUB_DIR="+dir,
		"ELASTICSEARCH_URL="+elasticsearchURL,
		"ELASTICSEARCH_USERNAME="+username,
		"ELASTICSEARCH_PASSWORD=stub-secret",
	)
	out, _ := cmd.CombinedOutput()
	if len(out) > 8192+4096 {
		t.Fatalf("diagnostics not bounded to 8 KiB: got %d bytes", len(out))
	}
}

// TestScriptsDoNotLeakPasswordOrHTTP verifies the generated scripts keep the
// password in the environment, never fall back to HTTP and never enable xtrace.
func TestScriptsDoNotLeakPasswordOrHTTP(t *testing.T) {
	scripts := readinessScript() + acceptanceScript("")
	if strings.Contains(scripts, password) {
		t.Fatalf("password literal must not appear in generated scripts")
	}
	if strings.Contains(scripts, "set -x") {
		t.Fatalf("xtrace must not be enabled")
	}
	if strings.Contains(scripts, "http://") {
		t.Fatalf("scripts must not reference plain HTTP")
	}
	if strings.Contains(scripts, "--fail") {
		t.Fatalf("readiness/template curl must not use --fail")
	}
	if strings.Contains(scripts, "timeout=500s") {
		t.Fatalf("old single request must be gone")
	}
	if !strings.Contains(scripts, "--insecure") || !strings.Contains(scripts, "--connect-timeout 2") {
		t.Fatalf("expected bounded HTTPS curl flags")
	}
}

// TestModuleSourceMeetsPlan verifies the static wiring required by the plan.
func TestModuleSourceMeetsPlan(t *testing.T) {
	raw, err := os.ReadFile("main.go")
	if err != nil {
		t.Fatalf("read main.go: %v", err)
	}
	src := string(raw)

	for _, want := range []string{
		`elasticsearchURL string = "https://elasticsearch.svc:9200"`,
		`WithEnvVariable("ELASTICSEARCH_URL", elasticsearchURL)`,
		`readinessScript()`,
		`WithSecretVariable("ELASTICSEARCH_PASSWORD"`,
	} {
		if !strings.Contains(src, want) {
			t.Errorf("main.go missing %q", want)
		}
	}

	acceptance := functionBody(src, "func (h *Elasticsearch) TestAcceptance(")
	debug := functionBody(src, "func (h *Elasticsearch) DebugTest(")
	for name, body := range map[string]string{"TestAcceptance": acceptance, "DebugTest": debug} {
		if !strings.Contains(body, "readinessScript()") {
			t.Errorf("%s must use the shared readiness helper", name)
		}
		if !strings.Contains(body, `WithServiceBinding("elasticsearch.svc", esService)`) {
			t.Errorf("%s must bind the elasticsearch.svc service", name)
		}
		if !strings.Contains(body, `WithEnvVariable("ELASTICSEARCH_URL", elasticsearchURL)`) ||
			!strings.Contains(body, `WithEnvVariable("ELASTICSEARCH_USERNAME", username)`) ||
			!strings.Contains(body, `WithSecretVariable("ELASTICSEARCH_PASSWORD"`) {
			t.Errorf("%s must set all three Elasticsearch env variables", name)
		}
	}

	for _, forbidden := range []string{
		`xpack.security.enabled`,
		`alpine/curl`,
		`panic(`,
		`sleep 10`,
		`timeout=500s`,
		`defer esService.Stop(ctx)`,
	} {
		if strings.Contains(src, forbidden) {
			t.Errorf("main.go must not contain %q", forbidden)
		}
	}

	if strings.Count(src, "readinessScript()") < 3 {
		t.Errorf("readinessScript must be defined and reused by both consumers")
	}
}

// functionBody returns src starting at the first occurrence of the function
// signature up to the next top-level "func " declaration.
func functionBody(src, signature string) string {
	start := strings.Index(src, signature)
	if start < 0 {
		return ""
	}
	rest := src[start+len(signature):]
	if end := strings.Index(rest, "\n// "); end >= 0 {
		return rest[:end]
	}
	return rest
}
